"""Vendored domain-agnostic base classes (from state_bench). Stdlib only."""
from __future__ import annotations

from abc import ABC, abstractmethod
from typing import Any, Callable


class DictMixin:
    """Standard to_dict/from_dict for flat dataclasses."""

    def to_dict(self) -> dict[str, Any]:
        return {fn: getattr(self, fn) for fn in self.__dataclass_fields__}

    @classmethod
    def from_dict(cls, data: dict[str, Any]):
        return cls(**{k: v for k, v in data.items() if k in cls.__dataclass_fields__})


class BaseEnvironment(ABC):
    """Abstract base for domain environments."""

    def __init__(self, env_data: Any, now: str):
        self.now = now

    @property
    @abstractmethod
    def tool_handlers(self) -> dict[str, Callable]:
        ...

    @abstractmethod
    def get_full_snapshot(self) -> dict[str, dict[str, dict[str, Any]]]:
        ...

    @staticmethod
    def parse_bool(value: Any) -> bool | None:
        if value is None:
            return None
        if isinstance(value, bool):
            return value
        if isinstance(value, str):
            return value.lower() in ("true", "1", "yes")
        return bool(value)

#!/usr/bin/env python3
"""STATE-Bench portable domain skill CLI.

Commands:
  tools                                      Print the domain tool schemas (OpenAI function format).
  call  <tool> --args '<json>' [--now <iso>]  Run a tool against the unified world.db (reads/mutates it).
  reset                                      Clear this skill's multi-step session gates (no-op on data).

State model: domain data lives in the unified per-task `world.db` (seeded fresh
into /workspace by the runner). `ENV_DATA_CLASS.load()` reads this skill's scoped
slice from world.db and `.save()` writes mutations straight back — there is no
db.json seed and no state.json working copy. Multi-step gates (policy-check ->
preview -> confirm) still persist in a local `session.json` under the workspace
(fresh per task since skills upload clean into each sandbox). `reset` clears those
gates; the data itself is re-seeded per task by the runner. By default the session
file lives in `<skill>/.state/`; override with --workspace.
"""
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))

from domain_meta import DEFAULT_NOW, DEFAULT_USER, ENV_CLASS, ENV_DATA_CLASS, SAVE_MAP  # noqa: E402
from tools import TOOL_SCHEMAS, WRITE_TOOL_NAMES  # noqa: E402


# --- session-state (sets/tuples) JSON codec -------------------------------
def _enc(o):
    if isinstance(o, set):
        return {"__set__": [_enc(x) for x in o]}
    if isinstance(o, tuple):
        return {"__tuple__": [_enc(x) for x in o]}
    if isinstance(o, dict):
        return {k: _enc(v) for k, v in o.items()}
    if isinstance(o, list):
        return [_enc(x) for x in o]
    return o


def _dec(o):
    if isinstance(o, dict):
        if set(o.keys()) == {"__set__"}:
            return {_dec(x) for x in o["__set__"]}
        if set(o.keys()) == {"__tuple__"}:
            return tuple(_dec(x) for x in o["__tuple__"])
        return {k: _dec(v) for k, v in o.items()}
    if isinstance(o, list):
        return [_dec(x) for x in o]
    return o


def _emit(obj, code=0):
    print(json.dumps(obj, ensure_ascii=False, indent=2))
    sys.exit(code)


def _workspace(args) -> Path:
    return Path(args.workspace) if getattr(args, "workspace", None) else (HERE / ".state")


def _seed_if_needed(ws: Path) -> Path:
    """Ensure the workspace dir exists and return the (session-only) state path.

    Domain data now lives in world.db (see schemas.py), so there is no db.json to
    copy; this just guarantees the workspace dir for session.json.
    """
    ws.mkdir(parents=True, exist_ok=True)
    return ws / "state.json"


def cmd_tools(_args):
    _emit({"write_tools": WRITE_TOOL_NAMES, "default_user": DEFAULT_USER, "now": DEFAULT_NOW, "tools": TOOL_SCHEMAS})


def cmd_reset(args):
    ws = _workspace(args)
    for name in ("state.json", "session.json"):
        p = ws / name
        if p.exists():
            p.unlink()
    _emit({"ok": True, "reset": True, "workspace": str(ws),
           "note": "session gates cleared; domain data is re-seeded per task from world.db"})


def cmd_call(args):
    ws = _workspace(args)
    state_path = _seed_if_needed(ws)
    now = args.now or DEFAULT_NOW
    try:
        params = json.loads(args.args) if args.args else {}
    except json.JSONDecodeError as e:
        _emit({"error": f"--args must be valid JSON: {e}"}, 1)
    if not isinstance(params, dict):
        _emit({"error": "--args must be a JSON object"}, 1)

    env_data = ENV_DATA_CLASS.load(state_path)
    env = ENV_CLASS(env_data, now=now)

    session_path = ws / "session.json"
    if session_path.exists():
        for k, v in _dec(json.loads(session_path.read_text())).items():
            setattr(env, k, v)

    handler = env.tool_handlers.get(args.tool)
    if handler is None:
        _emit({"error": f"Unknown tool '{args.tool}'. Run `tools` to list available tools."}, 1)

    try:
        result = handler(params)
    except Exception as e:  # domain handlers raise on bad input; surface as JSON
        _emit({"error": f"{type(e).__name__}: {e}"}, 1)

    # Persist mutated DB (rebuild EnvironmentData from live indexes so created rows are captured).
    rebuilt = ENV_DATA_CLASS(**{field: list(getattr(env, attr).values()) for field, attr in SAVE_MAP.items()})
    rebuilt.save(state_path)

    # Persist multi-step session flags (policy-check / preview gates).
    sess_out = {k: v for k, v in vars(env).items() if k.startswith("_")}
    session_path.write_text(json.dumps(_enc(sess_out), indent=2))

    is_write = args.tool in WRITE_TOOL_NAMES
    _emit({"tool": args.tool, "is_write": is_write, "result": result})


def main():
    p = argparse.ArgumentParser(description="STATE-Bench portable domain skill CLI")
    sub = p.add_subparsers(dest="cmd", required=True)
    sub.add_parser("tools").set_defaults(fn=cmd_tools)
    pr = sub.add_parser("reset")
    pr.add_argument("--workspace", default=None)
    pr.set_defaults(fn=cmd_reset)
    pc = sub.add_parser("call")
    pc.add_argument("tool")
    pc.add_argument("--args", default="{}")
    pc.add_argument("--now", default=None)
    pc.add_argument("--workspace", default=None)
    pc.set_defaults(fn=cmd_call)
    a = p.parse_args()
    a.fn(a)


if __name__ == "__main__":
    main()

"""Stateful customer support environment with tool handlers.

The CustomerSupportEnvironment holds the in-memory database and provides tool handler
methods as bound functions. Each evaluation run gets a fresh deep copy.
"""

from __future__ import annotations

import re
from datetime import datetime
from typing import Any

import policies
from schemas import (
    CSEnvironmentData,
    Customer,
    Order,
    OrderItem,
    Product,
    Warranty,
)
from core import BaseEnvironment


class CustomerSupportEnvironment(BaseEnvironment):
    """Stateful environment wrapping products, orders, items, customers, warranties and policy engine."""

    def __init__(self, env_data: CSEnvironmentData, now: str):
        super().__init__(env_data, now)
        self.products: dict[str, Product] = {p.product_id: p for p in env_data.products}
        self.orders: dict[str, Order] = {o.order_id: o for o in env_data.orders}
        self.order_items: dict[str, OrderItem] = {i.item_id: i for i in env_data.order_items}
        self.customers: dict[str, Customer] = {c.customer_id: c for c in env_data.customers}
        self.warranties: dict[str, Warranty] = {w.warranty_id: w for w in env_data.warranties}

        # Policy gate: track which policy topics have been looked up
        self._policies_checked: set[str] = set()

        # Two-step enforcement: track previewed operations per tool
        self._previewed: dict[str, set[str]] = {
            "return": set(),
            "refund": set(),
            "cancel": set(),
            "exchange": set(),
            "warranty_claim": set(),
        }
        self._previewed_refunds: dict[str, set[tuple[str, int | float]]] = {}

    def get_orders_snapshot(self) -> dict[str, dict[str, Any]]:
        """Return a snapshot for assertion checking.

        Keys include order_ids, item_ids, AND warranty_ids so that
        DBAssertion.booking_id (used as generic entity_id) can reference
        any entity type.
        """
        snapshot: dict[str, dict[str, Any]] = {}
        for oid, order in self.orders.items():
            snapshot[oid] = order.to_dict()
        for iid, item in self.order_items.items():
            snapshot[iid] = item.to_dict()
        for wid, warranty in self.warranties.items():
            snapshot[wid] = warranty.to_dict()
        return snapshot

    def get_full_snapshot(self) -> dict[str, dict[str, dict[str, Any]]]:
        """Return all mutable entities indexed by type and ID for StateDiff."""
        return {
            "orders": {oid: o.to_dict() for oid, o in self.orders.items()},
            "order_items": {iid: i.to_dict() for iid, i in self.order_items.items()},
            "customers": {cid: c.to_dict() for cid, c in self.customers.items()},
            "warranties": {wid: w.to_dict() for wid, w in self.warranties.items()},
        }

    def _get_items_for_order(self, order_id: str) -> list[OrderItem]:
        """Get all OrderItems belonging to an order."""
        return [item for item in self.order_items.values() if item.order_id == order_id]

    def _get_warranty_for_item(self, item_id: str) -> Warranty | None:
        """Get warranty for an item, if any."""
        for w in self.warranties.values():
            if w.item_id == item_id:
                return w
        return None

    # -------------------------------------------------------------------
    # READ tools
    # -------------------------------------------------------------------

    def get_order(self, params: dict[str, Any]) -> dict[str, Any]:
        """Retrieve full order details including all items and product info."""
        order_id = params.get("order_id", "")
        order = self.orders.get(order_id)
        if not order:
            return {"error": f"Order {order_id} not found."}

        items = self._get_items_for_order(order_id)
        items_data = []
        for item in items:
            product = self.products.get(item.product_id)
            item_dict = item.to_dict()

        item_dict = item.to_dict()
        if product:
            item_dict["product"] = {
                "product_id": product.product_id,
                "name": product.name,
                "category": product.category,
                "price": product.price,
                "current_price": product.current_price,
                "return_window_days": product.return_window_days,
                "warranty_months": product.warranty_months,
                "in_stock": product.in_stock,
            }
        items_data.append(item_dict)

    result = order.to_dict()
    result["items"] = items_data
    return result

def get_customer(self, params: dict[str, Any]) -> dict[str, Any]:
    """Retrieve customer profile."""
    customer_id = params.get("customer_id", "")
    customer = self.customers.get(customer_id)
    if not customer:
        return {"error": f"Customer {customer_id} not found."}
    result = customer.to_dict()
    # Add membership benefit summary
    tier = customer.membership_tier
    result["benefits"] = {
        "return_window_extension": f"+{policies.TIER_RETURN_EXTENSION.get(tier, 0)} days",
        "compensation_multiplier": f"{policies.TIER_COMPENSATION_MULTIPLIER.get(tier, 1.0)}x",
        "restocking_fee_waiver": tier == "platinum",
        "prime_shipping": customer.has_prime_shipping,
    }
    return result

def search_products(self, params: dict[str, Any]) -> dict[str, Any]:
    """Search task-local products by name, category, or subcategory."""
    query = str(params.get("query", "")).strip()
    if not query:
        return {"error": "query is required."}

    query_terms = [term for term in re.split(r"[^a-z0-9]+", query.lower()) if term]
    matches: list[tuple[int, str, str, Product]] = []
    for product in self.products.values():
        name = product.name.lower()
        category = product.category.lower()
        subcategory = product.subcategory.lower()
        score = 0
        matched_field = ""
        if query.lower() == name:
            score += 100
            matched_field = "name"
        elif query.lower() in name:
            score += 70
            matched_field = "name"
        for term in query_terms:
            if term in name:
                score += 10
                matched_field = matched_field or "name"
            if term == category or term in category:
                score += 5
                matched_field = matched_field or "category"
            if term == subcategory or term in subcategory:
                score += 7
                matched_field = matched_field or "subcategory"
        if score > 0:
            matches.append((score, product.name, matched_field, product))

    matches.sort(key=lambda row: (-row[0], row[1], row[3].product_id))
    return {
        "query": query,
        "results": [
            {
                "product_id": product.product_id,
                "name": product.name,
                "matched_field": matched_field,
                "category": product.category,
                "subcategory": product.subcategory,
                "in_stock": product.in_stock,
            }
            for _score, _name, matched_field, product in matches
        ],
    }

def get_product_details(self, params: dict[str, Any]) -> dict[str, Any]:
    """Retrieve full product details by exact product_id."""
    product_id = params.get("product_id", "")
    product = self.products.get(product_id)
    if not product:
        return {"error": f"Product {product_id} not found."}
    return product.to_dict()

